    class InputRejected(ValueError):
        """No trustworthy binding context exists; no proposal can be fabricated."""


    class ProposalOverflow(ValueError):
        pass


    class BindingContext:
        """Caller-owned current kernel binding; construction is not authentication.

        A separately verified adapter must supply this from authoritative state.
        Offline fixtures/replays can supply it for diagnostic execution only.
        """
        __slots__ = ("_values", "_model_id")

        def __init__(self, binding, model_id):
            if not isinstance(binding, dict) or set(binding) != {"turn_id", "state_revision", "policy_hash", "api_hash"}:
                raise InputRejected("Complete authoritative binding required")
            if not isinstance(binding["turn_id"], str) or not 1 <= len(binding["turn_id"]) <= 128:
                raise InputRejected("Valid turn ID required")
            if type(binding["state_revision"]) is not int or binding["state_revision"] < 0:
                raise InputRejected("Valid state revision required")
            if any(not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{64}", value)
                   for value in (binding["policy_hash"], binding["api_hash"], model_id)):
                raise InputRejected("Real policy/API/model SHA256 bindings required")
            object.__setattr__(self, "_values", tuple(binding[key] for key in ("turn_id", "state_revision", "policy_hash", "api_hash")))
            object.__setattr__(self, "_model_id", model_id)

        def __setattr__(self, key, value):
            raise InputRejected("BindingContext is immutable")

        @property
        def model_id(self):
            return self._model_id

        def binding(self):
            return dict(zip(("turn_id", "state_revision", "policy_hash", "api_hash"), self._values))


    def tokens_v2(text):
        # Number tokens delexicalized before intent fitting; offsets use raw text.
        return ["<number>" if m.group().isdigit() else m.group().lower() for m in
                re.finditer(r"[A-Za-z]+(?:['\u2019][A-Za-z]+)?|\d+", text)]


    def _counts(items):
        result = dict()
        for item in items:
            result[item] = result.get(item, 0) + 1
        return result


    def feature_v2(snapshot, candidate=None, include_context=True):
        """Feature allowlist; never includes labels, IDs, hashes or canonical facts."""
        text = snapshot["utterance"]["text"]
        token = tokens_v2(text)
        f = _counts("w:" + t for t in token)
        for a, b in zip(token, token[1:]):
            key = "b:" + a + "/" + b
            f[key] = f.get(key, 0) + 1
        padded = "^" + " ".join(token) + "$"
        for i in range(len(padded) - 2):
            key = "c:" + padded[i:i + 3]
            f[key] = f.get(key, 0) + 1
        if include_context:
            context = ["phase=" + snapshot["phase"], "question=" + snapshot["question"]["role"],
                       "security_field=" + str(snapshot["question"].get("security_field", "none")),
                       "target_count=" + str(min(len(snapshot["targets"]), 3)),
                       "has_offer=" + str(bool(snapshot["spoken_offers"])),
                       "has_readback=" + str(bool(snapshot["active_readback"]))]
            for item in context:
                f["ctx:" + item] = 3.0
                for word in token[:16]:
                    f["cross:" + item + "/" + word] = 1.0
            requested_indices = snapshot["question"].get("target_indices", [])
            if len(requested_indices) == 1:
                matched = [item for item in snapshot["pending"] if item.get("target_index") == requested_indices[0]]
                f["pending:current_target_count=" + str(len(matched))] = 1.0
                for component in COMPONENTS:
                    for item in matched:
                        status = item.get("components", {}).get(component, {}).get("status", "unobserved")
                        f["pending:current:" + component + "=" + str(status)] = 1.0
            else:
                f["pending:current_target=unresolved"] = 1.0
        if candidate:
            start, end = candidate["start"], candidate["end"]
            for item in ("component=" + candidate["name"], "surface=" + " ".join(tokens_v2(text[start:end])),
                         "suffix=" + " ".join(tokens_v2(text[start:end]))[-4:], "tail=" + str(end == len(text)),
                         "fragment=" + str(text[start:end].rstrip().endswith(("...", "\u2026", "-")))):
                f["span:" + item] = 3.0
            prefix = text[max(0, start - 32):start].lower()
            for word in tokens_v2(prefix):
                f["left:" + word] = 1.0
        norm = sum(v * v for v in f.values()) ** .5 or 1.0
        return dict((key, value / norm) for key, value in f.items())


    def distribution_v2(head, feature):
        logits = [bias + sum(weight.get(key, 0.0) * value for key, value in feature.items())
                  for bias, weight in zip(head["bias"], head["weights"])]
        if not logits or len(logits) != len(head["labels"]) or any(not -float("inf") < value < float("inf") for value in logits):
            raise ValueError("Malformed or nonfinite linear head")
        top = max(logits)
        exp = [2.718281828459045 ** (value - top) for value in logits]
        denom = sum(exp)
        return dict(zip(head["labels"], [value / denom for value in exp]))


    def binary_score_v2(head, feature):
        logit = head["bias"] + sum(head["weights"].get(key, 0.0) * value for key, value in feature.items())
        if not -float("inf") < logit < float("inf"):
            raise ValueError("Nonfinite binary head")
        return 1.0 / (1.0 + 2.718281828459045 ** (-max(-50, min(50, logit))))


    def candidate_spans_v2(snapshot, include_context=True):
        """Bounded lexical span proposals, not gold or complete value parsing."""
        text = snapshot["utterance"]["text"]
        patterns = {"amount": r"\b(?:\d+(?:[.,]\d+)?|(?:one|two|three|four|five|six|seven|eight|nine|ten|twenty|hundred|thousand)(?:\s+(?:one|two|three|four|five|six|seven|eight|nine|ten|twenty|hundred|thousand|and))*)\b",
                    "date": r"\b(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|tomorrow|today|next week|Fri\.\.\.|Mon\.\.\.|\d{4}-\d{2}-\d{2})",
                    "time": r"\b\d{1,2}:\d{2}\b"}
        question_role = snapshot["question"]["role"]
        if include_context and question_role == "security":
            patterns = {"security_answer": r"\S(?:.*\S)?"}
        candidates = []
        for name, pattern in patterns.items():
            for match in re.finditer(pattern, text, re.I):
                end = match.end()
                if name == "amount" and match.group().lower().endswith(" and") and re.match(r"\s+(?:the\s+)?(?:date|time|security)\b", text[end:], re.I):
                    end -= 4
                candidates.append({"name": name, "start": match.start(), "end": end})
        if len(candidates) > 16:
            raise ProposalOverflow("More than 16 span candidates; no silent truncation")
        return candidates


    def qualifiers_v2(snapshot):
        """Evidence channels remain separate from learned intent/completeness."""
        text = snapshot["utterance"]["text"]
        patterns = {"correction": r"\b(?:actually|I meant|I mean|no wait|revise|correct)\b",
                    "negation": r"\b(?:not|never|cannot|can't|don't|won't|no)\b",
                    "qualifier": r"\b(?:if|maybe|perhaps|provided|but)\b"}
        spans = []
        for role, pattern in patterns.items():
            for match in re.finditer(pattern, text, re.I):
                spans.append({"turn_id": snapshot["turn_id"], "start": match.start(), "end": match.end(), "role": role})
        if len(spans) > 16:
            raise ProposalOverflow("More than 16 qualifier spans; no silent truncation")
        return sorted(spans, key=lambda span: (span["start"], span["end"]))


    def binding_v2(snapshot):
        return {key: snapshot[key] for key in ("turn_id", "state_revision", "policy_hash", "api_hash")}


    def _reason(reason, clause_id=None, components=None):
        return {"reason": reason, "clause_id": clause_id, "target_indices": [], "components": components or []}


    def neutral_v2(binding_context, reason):
        return {"schema_version": "semantic_proposal.v1", "binding": binding_context.binding(), "model_id": binding_context.model_id,
                "status": "abstain", "primary": None, "secondary": [], "clauses": [], "corrections": [],
                "consent_signal": {"kind": "ambiguous", "evidence": [], "candidate_readback_id": None,
                                   "has_new_terms": "unknown", "decision": "descriptive_only"},
                "ood": {"decision": "unassessed", "known_feature_fraction": None, "nearest_train_similarity": None,
                        "margin": None, "reasons": [reason]}, "abstentions": [_reason(reason)]}


    def _check_snapshot(snapshot):
        if not isinstance(snapshot, dict) or set(snapshot) != set(INPUT_KEYS) or snapshot["schema_version"] != "semantic_input.v1":
            return "unknown_schema"
        if type(snapshot["state_revision"]) is not int or snapshot["state_revision"] < 0:
            return "stale_binding"
        for key in ("policy_hash", "api_hash"):
            if not isinstance(snapshot[key], str) or not re.fullmatch(r"[0-9a-f]{64}", snapshot[key]):
                return "stale_binding"
        if not isinstance(snapshot["turn_id"], str) or not 1 <= len(snapshot["turn_id"]) <= 128:
            return "stale_binding"
        utterance = snapshot["utterance"]
        if not isinstance(utterance, dict) or set(utterance) != {"text", "source", "source_turn_id", "complete_transport", "offset_unit"}:
            return "missing_input"
        if not isinstance(utterance["text"], str):
            return "missing_input"
        if len(utterance["text"]) > 4096:
            return "size_limit"
        if not utterance["text"].strip():
            return "missing_input"
        if utterance["source"] not in {"trusted_turn", "authored_fixture"}:
            return "untrusted_text"
        if utterance["source_turn_id"] != snapshot["turn_id"]:
            return "stale_binding"
        if utterance["complete_transport"] is not True:
            return "transport_truncated"
        if utterance["offset_unit"] != "python_unicode_codepoints":
            return "invalid_span"
        if not isinstance(snapshot["phase"], str) or not isinstance(snapshot["question"], dict) or not isinstance(snapshot["question"].get("role"), str):
            return "missing_input"
        if any(not isinstance(snapshot[key], list) or len(snapshot[key]) > 16 for key in ("targets", "pending", "spoken_offers")):
            return "size_limit"
        if any(not isinstance(item, dict) for key in ("targets", "pending", "spoken_offers") for item in snapshot[key]):
            return "missing_input"
        offer_ids = [item.get("offer_id") for item in snapshot["spoken_offers"]]
        if any(not isinstance(v, str) for v in offer_ids) or len(set(offer_ids)) != len(offer_ids):
            return "unresolved_reference"
        return None


    def _predict_v2(input_snapshot, model_bundle, binding_context=None):
        """Descriptive, schema-aligned diagnostic; unsupported heads fail closed.

        Binding/model hashes are supplied by the trusted offline loader/wrapper.
        This does not authenticate a caller or create a Freya trusted-turn adapter.
        """
        if not isinstance(binding_context, BindingContext):
            raise InputRejected("Caller-owned authoritative BindingContext is required")
        reason = _check_snapshot(input_snapshot)
        if reason:
            return neutral_v2(binding_context, reason)
        if binding_v2(input_snapshot) != binding_context.binding() or model_bundle.get("model_id") != binding_context.model_id:
            return neutral_v2(binding_context, "stale_binding")
        model = model_bundle["model"]
        if model.get("format") != FORMAT_V2:
            return neutral_v2(binding_context, "unknown_schema")
        if not model.get("qualification", {}).get("primary", {}).get("trained", False):
            return neutral_v2(binding_context, "untrained_head")
        text = input_snapshot["utterance"]["text"]
        vector = feature_v2(input_snapshot, include_context=model.get("include_context", True))
        if len(vector) > 4096:
            return neutral_v2(binding_context, "size_limit")
        probs = distribution_v2(model["heads"]["primary"], vector)
        label = max(probs, key=lambda key: (probs[key], key))
        evidence = [{"turn_id": input_snapshot["turn_id"], "start": 0, "end": len(text), "role": "intent"}]
        def decision(score, trained=True):
            return {"score": score, "calibrated_probability": None, "calibration_id": None,
                    "decision": "abstain", "abstain_reason": "uncalibrated" if trained else "untrained_head"}
        primary = dict(decision(probs[label]), label=label, evidence=evidence)
        secondary = []
        for secondary_label, head in sorted(model["secondary"].items()) if model["qualification"].get("secondary", {}).get("trained") else []:
            score = binary_score_v2(head, vector)
            if score >= .5 and secondary_label not in {label, "unknown"}:
                secondary.append(dict(decision(score), label=secondary_label, evidence=evidence))
        if len(secondary) > 16:
            return neutral_v2(binding_context, "size_limit")
        try:
            qualifiers = qualifiers_v2(input_snapshot)
            candidates = candidate_spans_v2(input_snapshot, model.get("include_context", True))
        except ProposalOverflow:
            return neutral_v2(binding_context, "size_limit")
        component_rows = []
        for candidate in candidates:
            span_vector = feature_v2(input_snapshot, candidate, model.get("include_context", True))
            completion_trained = model["qualification"].get("component_completion", {}).get("trained", False)
            polarity_trained = model["qualification"].get("component_polarity", {}).get("trained", False)
            support = model.get("component_support", {}).get(candidate["name"])
            if support is not None:
                completion_trained = completion_trained and support.get("component_completion", {}).get("observed_samples", 0) > 0
                polarity_trained = polarity_trained and support.get("component_polarity", {}).get("observed_samples", 0) > 0
            completion_scores = distribution_v2(model["heads"]["component_completion"], span_vector) if completion_trained else {"ambiguous": 0.0}
            polarity_scores = distribution_v2(model["heads"]["component_polarity"], span_vector) if polarity_trained else {"unknown": 0.0}
            # Heads are trained on weak authored span labels, but not qualified.
            component_rows.append({"name": candidate["name"], "completion": max(completion_scores, key=completion_scores.get),
                                   "polarity": max(polarity_scores, key=polarity_scores.get),
                                   "evidence": [{"turn_id": input_snapshot["turn_id"], "start": candidate["start"], "end": candidate["end"], "role": "value"}],
                                   "reference": None, "confidence": decision(0.0, trained=completion_trained and polarity_trained)})
        # At most one candidate per name can fit the contract until clause/target heads exist.
        counts = dict()
        for component in component_rows:
            counts[component["name"]] = counts.get(component["name"], 0) + 1
        components = [component for component in component_rows if counts[component["name"]] == 1]
        for name in COMPONENTS:
            if counts.get(name, 0) != 1:
                unresolved_evidence = [span for item in component_rows if item["name"] == name for span in item["evidence"]]
                components.append({"name": name, "completion": "ambiguous", "polarity": "unknown", "evidence": unresolved_evidence,
                                   "reference": None, "confidence": decision(0.0, trained=False)})
        clause_id = input_snapshot["turn_id"] + ":c0"
        reference, readback_reference, references_reason = reference_candidate_v2(input_snapshot, label, model.get("include_context", True))
        clauses = [{"clause_id": clause_id, "intent": primary, "scope": "unresolved", "target_refs": [],
                    "collective_id": None, "amount_scope": "unresolved" if any(c["name"] == "amount" for c in components) else "absent",
                    "components": components, "qualifiers": qualifiers, "offer_reference": reference}]
        correction_evidence = [s for s in qualifiers if s["role"] == "correction"]
        corrections = [{"target_refs": [], "components": ["unknown"], "evidence": correction_evidence,
                        "supersedes": None, "status": "candidate"}] if correction_evidence else []
        abstentions = [_reason("uncalibrated"), _reason("untrained_head", clause_id, ["recipient", "allocation"]), _reason("unknown_target", clause_id)]
        if references_reason:
            abstentions.append(_reason(references_reason, clause_id))
        if correction_evidence:
            abstentions.append(_reason("unknown_correction_scope", clause_id))
        if any(value > 1 for value in counts.values()):
            abstentions.append(_reason("inconsistent_heads", clause_id))
        # Consent head absent: retain ambiguity, never convert predicted affirmation to consent.
        consent = {"kind": "ambiguous", "evidence": [], "candidate_readback_id": readback_reference,
                   "has_new_terms": "unknown", "decision": "descriptive_only"}
        return {"schema_version": "semantic_proposal.v1", "binding": binding_v2(input_snapshot), "model_id": model_bundle["model_id"],
                "status": "abstain", "primary": primary, "secondary": secondary, "clauses": clauses,
                "corrections": corrections, "consent_signal": consent,
                "ood": {"decision": "unassessed", "known_feature_fraction": sum(key in model["vocabulary"] for key in vector) / max(1, len(vector)),
                        "nearest_train_similarity": None, "margin": sorted(probs.values(), reverse=True)[0] - sorted(probs.values(), reverse=True)[1],
                        "reasons": ["uncalibrated"]}, "abstentions": abstentions}


    def predict_v2(input_snapshot, model_bundle, binding_context=None):
        if not isinstance(binding_context, BindingContext):
            raise InputRejected("Caller-owned authoritative BindingContext is required")
        try:
            return _predict_v2(input_snapshot, model_bundle, binding_context)
        except (KeyError, TypeError, ValueError, IndexError, AttributeError, OverflowError):
            return neutral_v2(binding_context, "runtime_failure")


    def reference_candidate_v2(snapshot, predicted_label, include_context=True):
        """Exact immutable ID from an actually spoken context reference, no terms."""
        if not include_context:
            return None, None, "unresolved_reference" if predicted_label in {"offer_acceptance", "readback_affirmation"} else None
        if predicted_label == "readback_affirmation":
            readback = snapshot["active_readback"]
            if not isinstance(readback, dict) or not isinstance(readback.get("readback_id"), str) or readback.get("valid") is not True or readback.get("completed_speech") is not True:
                return None, None, "unresolved_reference"
            if readback.get("state_revision") != snapshot["state_revision"]:
                return None, None, "stale_binding"
            return None, readback["readback_id"], None
        reference = snapshot["question"].get("spoken_offer_id")
        if predicted_label != "offer_acceptance" or reference is None:
            return None, None, "unresolved_reference" if predicted_label == "offer_acceptance" else None
        matches = [offer for offer in snapshot["spoken_offers"] if offer["offer_id"] == reference]
        if len(matches) != 1 or matches[0].get("superseded") is not False or matches[0].get("spoken_turn_id") is None:
            return None, None, "unresolved_reference"
        if matches[0].get("state_revision", 0) > snapshot["state_revision"]:
            return None, None, "stale_binding"
        return reference, None, None


    def check_deferred_refusal_v2(authoritative_pending, event):
        """Pure revision check; returns diagnosis only, never changes bank/pending state."""
        if not isinstance(event, dict) or type(event.get("target_index")) is not int or type(event.get("component_revision")) is not int or not isinstance(event.get("offer_id"), str):
            return {"eligible_for_kernel_review": False, "reason": "malformed_revision_event"}
        target = event.get("target_index")
        current = next((p for p in authoritative_pending if p.get("target_index") == target), None)
        if current is None:
            return {"eligible_for_kernel_review": False, "reason": "unknown_target"}
        if type(current.get("component_revision")) is not int or not isinstance(current.get("spoken_offer_id"), str):
            return {"eligible_for_kernel_review": False, "reason": "missing_authoritative_revision"}
        if event.get("component_revision") != current.get("component_revision"):
            return {"eligible_for_kernel_review": False, "reason": "superseded_component_revision"}
        if event.get("offer_id") != current.get("spoken_offer_id"):
            return {"eligible_for_kernel_review": False, "reason": "superseded_offer_reference"}
        return {"eligible_for_kernel_review": True, "reason": "matching_revision_requires_external_policy"}

    BUNDLE = dict(model_id='4b96a26d0b99ed2ff2d774d7678131c4cb14960b462ba48bcc3790972d31b427', model=MODEL)
    """Pure offline source/reference admission. No I/O, value normalization or state change.

    Registry/pending are independently sourced deterministic wrapper arguments.
    Constructing a TrustedCallV3 or passing two equal copies proves no authentication.
    No such lossless/fresh Freya ingress is claimed by this prototype.
    """


    class TrustedCallV3:
        __slots__=("binding_context","call_local_id","source_event_id","event_ordinal","text","complete_transport","question_identity","target_mapping")
        def __init__(self,binding_context,call_local_id,source_event_id,event_ordinal,text,complete_transport,question_identity=None,target_mapping=None):
            if not isinstance(binding_context,BindingContext) or type(call_local_id) is not str or not call_local_id or source_event_id != binding_context.binding()["turn_id"] or type(event_ordinal) is not int or event_ordinal < 0 or type(text) is not str or complete_transport is not True:
                raise InputRejected("Independent complete current user-event context required")
            if question_identity is not None and (type(question_identity) is not tuple or len(question_identity)!=3 or any(type(v) is not str or not v for v in question_identity)):
                raise InputRejected("Independent question ID/speech ID/role tuple required")
            if target_mapping is not None and (type(target_mapping) is not tuple or any(type(v) is not tuple or len(v)!=2 or type(v[0]) is not int or type(v[1]) is not str or not v[1] for v in target_mapping)):
                raise InputRejected("Independent immutable index/target ID mapping required")
            for key,value in zip(self.__slots__,(binding_context,call_local_id,source_event_id,event_ordinal,text,complete_transport,question_identity,target_mapping)):
                object.__setattr__(self,key,value)
        def __setattr__(self,key,value):
            raise InputRejected("Trusted current source fixture is immutable")


    def validate_ingress_v3(snapshot, trusted):
        if not isinstance(trusted,TrustedCallV3):
            raise InputRejected("No independent trusted source context; no fabricated binding")
        reason=_check_snapshot(snapshot)
        if reason:
            return reason
        if snapshot["phase"] not in {"callback","payment","readback","recipient","security","support"} or snapshot["question"]["role"] not in {"amount","callback","date","none","offer","payment","readback","recipient","security","support"}:
            return "unknown_schema"
        if snapshot["call_local_id"] != trusted.call_local_id or {k:snapshot[k] for k in trusted.binding_context.binding()} != trusted.binding_context.binding():
            return "stale_binding"
        if snapshot["utterance"]["text"] != trusted.text or snapshot["utterance"]["source_turn_id"] != trusted.source_event_id:
            return "untrusted_text"
        if trusted.question_identity is not None and tuple(snapshot["question"].get(k) for k in ("question_id","spoken_turn_id","role")) != trusted.question_identity:
            return "stale_binding"
        targets=[t.get("index") for t in snapshot["targets"] if type(t) is dict]
        if len(targets) != len(snapshot["targets"]) or any(type(i) is not int or i < 0 for i in targets) or len(targets) != len(set(targets)):
            return "unknown_target"
        if any(type(i) is not int or i not in targets for i in snapshot["question"].get("target_indices",[])):
            return "unknown_target"
        if trusted.target_mapping is not None and set((t.get("index"),t.get("product_id")) for t in snapshot["targets"]) != set(trusted.target_mapping):
            return "unknown_target"
        return None


    def _failed(kind,reason,checks=None):
        return {"candidate_id_or_null":None,"reference_kind":kind,"reason":reason,"dependency_checks":checks or [],"diagnosis_only":True}


    def resolve_reference_v3(snapshot,label,trusted,registry,authoritative_state,new_terms=False):
        """Historical speech revision3/current4 can be fresh; component tokens decide.

        Opaque source event IDs are never sorted or parsed as counters. Registry entries
        are not constructed from the current snapshot. Values are never returned.
        """
        reason=validate_ingress_v3(snapshot,trusted)
        if reason: return _failed(None,reason)
        if trusted.question_identity is None or trusted.target_mapping is None:
            return _failed(None,"unresolved_reference",["independent_question_and_target_identity_unavailable"])
        role=snapshot["question"]["role"]
        if label == "offer_acceptance" and role == "offer":
            kind="offer"; reference_id=snapshot["question"].get("spoken_offer_id")
        elif label == "readback_affirmation" and role == "readback":
            kind="readback"; reference_id=(snapshot.get("active_readback") or {}).get("readback_id")
        else:
            return _failed(None,"unresolved_reference")
        if new_terms:
            return _failed(kind,"stale_binding",["same_turn_new_terms_blocks_prior_confirmation"])
        if type(reference_id) is not str or not 1 <= len(reference_id) <= 128:
            return _failed(kind,"unresolved_reference")
        try:
            events=registry["source_events"]; references=registry["references"]
            ids=[event["event_id"] for event in events]
            rids=[entry["reference_id"] for entry in references]
            if any(type(i) is not str or not 1<=len(i)<=128 for i in ids+rids):
                return _failed(kind,"unresolved_reference",["invalid_registry_id"])
            if len(ids) != len(set(ids)) or len(rids) != len(set(rids)):
                return _failed(kind,"unresolved_reference",["duplicate_registry_id"])
            current=next(event for event in events if event["event_id"]==trusted.source_event_id)
            if current["call_local_id"] != trusted.call_local_id or current["role"] != "user" or type(current["ordinal"]) is not int or current["ordinal"] != trusted.event_ordinal or current["completed"] is not True:
                return _failed(kind,"stale_binding")
            entry=next(entry for entry in references if entry["reference_id"]==reference_id)
            speech=next(event for event in events if event["event_id"]==entry["spoken_event_id"])
            revision=entry["created_state_revision"]
            if type(revision) is not int or revision < 0 or revision > snapshot["state_revision"]:
                return _failed(kind,"stale_binding",["explicit_historical_revision_required"])
            if entry["kind"] != kind or entry["call_local_id"] != trusted.call_local_id or speech["call_local_id"] != trusted.call_local_id or entry["question_id"] != snapshot["question"].get("question_id"):
                return _failed(kind,"unresolved_reference")
            if speech["role"] != "assistant" or type(speech["ordinal"]) is not int or not speech["ordinal"] < trusted.event_ordinal or speech["completed"] is not True or entry["completed_speech"] is not True or entry["superseded_or_invalidated"] is not False:
                return _failed(kind,"stale_binding")
            if snapshot["question"].get("spoken_turn_id") != entry["spoken_event_id"] or any(entry[k] != snapshot[k] for k in ("policy_hash","api_hash")):
                return _failed(kind,"stale_binding")
            targets=entry["target_ids"]
            if not targets or len(targets) != len(set(targets)) or any(t not in authoritative_state["targets"] for t in targets):
                return _failed(kind,"unknown_target")
            expected_indices={authoritative_state["targets"][t]["target_index"] for t in targets}
            if expected_indices != set(snapshot["question"].get("target_indices",[])):
                return _failed(kind,"unknown_target")
            dependencies=entry["dependency_component_tokens"]
            specific=entry["base_component_tokens" if kind=="offer" else "readback_component_tokens"]
            terms=entry["immutable_terms" if kind=="offer" else "exact_spoken_terms"]
            if dependencies != specific or set(dependencies) != set(targets) or set(terms) != set(targets):
                return _failed(kind,"unresolved_reference",["dependency_set_missing"])
            checks=[]
            for target in targets:
                state=authoritative_state["targets"][target]
                if kind=="offer" and state.get("current_offer_id") != reference_id:
                    return _failed(kind,"stale_binding",["offer_is_not_current_target_offer"])
                if type(entry["target_disposition_epochs"][target]) is not str or not entry["target_disposition_epochs"][target] or entry["target_disposition_epochs"][target] != state["disposition_epoch"]:
                    return _failed(kind,"stale_binding")
                tokens=dependencies[target]
                if not tokens or set(tokens) != set(terms[target]):
                    return _failed(kind,"unresolved_reference",["term_component_tokens_missing"])
                for component,token in tokens.items():
                    current_token=state["components"][component]["revision"]
                    if type(token) is not str or not token or type(current_token) is not str or not current_token or token != current_token:
                        return _failed(kind,"stale_binding",checks+[target+":"+component+":changed_or_missing_token"])
                    checks.append(target+":"+component+":matched")
            if kind=="readback" and (entry["active_readback_id"] != reference_id or authoritative_state.get("active_readback_id") != reference_id):
                return _failed(kind,"stale_binding")
            return {"candidate_id_or_null":reference_id,"reference_kind":kind,"reason":None,"dependency_checks":checks,"diagnosis_only":True}
        except (KeyError,TypeError,ValueError,StopIteration):
            return _failed(kind,"unresolved_reference")


    def check_deferred_refusal_v3(event,state,registry):
        """Typed opaque revisions, target epoch and exact offer/event identity only."""
        try:
            target=state["targets"][event["target_id"]]
            if type(event["disposition_epoch"]) is not str or not event["disposition_epoch"] or event["disposition_epoch"] != target["disposition_epoch"]:
                return {"matches_current_target":False,"reason":"stale_binding","diagnosis_only":True}
            events=[e for e in registry["source_events"] if e["event_id"]==event["source_event_id"]]
            offers=[r for r in registry["references"] if r["reference_id"]==event["offer_id"] and r["kind"]=="offer"]
            if len(events)!=1 or len(offers)!=1 or event["offer_id"] != target.get("current_offer_id") or events[0]["role"] != "user" or events[0]["call_local_id"] != offers[0]["call_local_id"]:
                return {"matches_current_target":False,"reason":"unresolved_reference","diagnosis_only":True}
            tokens=event["component_tokens"]
            valid=bool(tokens) and all(type(token) is str and token and type(target["components"][name]["revision"]) is str and token==target["components"][name]["revision"] for name,token in tokens.items())
            return {"matches_current_target":valid,"reason":None if valid else "stale_binding","diagnosis_only":True}
        except (KeyError,TypeError,ValueError):
            return {"matches_current_target":False,"reason":"unresolved_reference","diagnosis_only":True}
    """Audited deterministic English candidate proposer; no semantic absence claim.

    Candidates are source-span hypotheses, not normalized values or qualified labels.
    No dataset labels are loaded. Unmatched/unreviewed candidates stay masked.
    """

    DETECTOR_VERSION="scoped_candidate_proposer.v3.1"
    COMPONENT_NAMES=("amount","date","time","security_answer","recipient","allocation")


    def clause_ranges_v3(text):
        cuts=[0]
        for match in re.finditer(r";|\n|(?<!\d)[.!?]\s+|\s+\bbut\b\s+",text,re.I):
            cuts.append(match.end())
        cuts.append(len(text))
        result=[]
        for start,end in zip(cuts,cuts[1:]):
            while start < end and text[start].isspace(): start+=1
            while start < end and text[end-1].isspace(): end-=1
            if start < end: result.append({"clause_id":"c"+str(len(result)),"start":start,"end":end})
        return result


    def detect_candidates_v3(text,question_role="none",targets=None,security_fields=None,locale="en"):
        if type(text) is not str or not text or len(text)>4096:
            return {"version":DETECTOR_VERSION,"status":"overflow" if type(text) is str and len(text)>4096 else "unsupported_context","candidates":[],"candidate_count":0,"clauses":[],"missing_kind_diagnostics":{},"absence_established":False}
        clauses=clause_ranges_v3(text)
        candidates=[]; exclusions=[]; unsupported=[]
        def add(kind,start,end,role_start=None,role_end=None,hint=None):
            if not 0 <= start < end <= len(text): return
            if any(c["kind"]==kind and c["start"]==start and c["end"]==end for c in candidates): return
            clause=next((c["clause_id"] for c in clauses if c["start"]<=start and end<=c["end"]),None)
            candidates.append({"candidate_id":"h"+str(len(candidates)),"kind":kind,"name":kind,"start":start,"end":end,
                               "clause_id_or_unknown":clause,"proposer_version":DETECTOR_VERSION,"possible_kinds":[kind],
                               "role_evidence_spans":[] if role_start is None else [{"start":role_start,"end":role_end}],
                               "detector_status":"candidate","validity_mask":False,"completion_hint":hint})
        if locale != "en":
            return {"version":DETECTOR_VERSION,"status":"unsupported_context","candidates":[],"candidate_count":0,"clauses":clauses,"missing_kind_diagnostics":dict.fromkeys(COMPONENT_NAMES,"unsupported_context"),"absence_established":False}
        if question_role == "security":
            # Descriptor is an independent wrapper argument, never a whole-turn regex.
            if not security_fields:
                unsupported.append("security_field_isolation_unavailable")
            else:
                for descriptor in security_fields:
                    if type(descriptor) is not dict or descriptor.get("source_bound") is not True or type(descriptor.get("start")) is not int or type(descriptor.get("end")) is not int or not 0<=descriptor["start"]<descriptor["end"]<=len(text):
                        unsupported.append("invalid_security_field_descriptor")
                        continue
                    add("security_answer",descriptor["start"],descriptor["end"])
            return {"version":DETECTOR_VERSION,"status":"unsupported_context" if unsupported else "candidate",
                    "candidates":candidates,"candidate_count":len(candidates),"clauses":clauses,
                    "missing_kind_diagnostics":dict.fromkeys(COMPONENT_NAMES,"unsupported_context"),
                    "absence_established":False,"surface_features_masked":True,"lost_admin_head_capability":True,"unsupported":unsupported}
        # Typed competing spans retained for false-candidate audit, never money labels.
        for match in re.finditer(r"\b(?:card|account)\s+(?:ending|number|suffix)(?:\s+in)?\s+([0-9]+)\b",text,re.I):
            exclusions.append({"kind":"identifier","start":match.start(1),"end":match.end(1),"role_start":match.start(),"role_end":match.start(1)})
        dates=(r"\b(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|today|tomorrow|next\s+week|this\s+week|another\s+date|that\s+date)\b",
               r"\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2}(?:st|nd|rd|th)?(?:,?\s+\d{4})?\b",
               r"\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2}[/-]\d{1,2}[/-]\d{4}\b",
               r"\b(?:on|next|Fri|Mon)(?:\s*)?(?:\.\.\.|\u2026)(?!\w)")
        for pattern in dates:
            for match in re.finditer(pattern,text,re.I):
                hint="unfinished" if match.group().rstrip().endswith(("...","\u2026")) else "complete_expression_unparsed"
                add("date",match.start(),match.end(),hint=hint)
        for match in re.finditer(r"\b\d{1,2}:\d{2}(?:\s*(?:am|pm))?\b",text,re.I):
            add("time",match.start(),match.end())
        numeric=r"\d+(?:[.,]\d+)?"
        words=r"(?:one|two|three|four|five|six|seven|eight|nine|ten|twenty|hundred|thousand)(?:\s+(?:one|two|three|four|five|six|seven|eight|nine|ten|twenty|hundred|thousand|and))*(?:\.\.\.|\u2026)?"
        for match in re.finditer(r"[$\u00a3\u20ac]\s*("+numeric+r")",text):
            add("amount",match.start(1),match.end(1),match.start(),match.start(1))
        pattern=r"\b(?:pay|paid|payment|amount|budget|afford)\b(?:\s+(?:is|of|was|about|around|only|a|total|to|be)){0,4}\s+[$\u00a3\u20ac]?\s*("+numeric+"|"+words+r")\b"
        for match in re.finditer(pattern,text,re.I):
            add("amount",match.start(1),match.end(1),match.start(),match.start(1))
        if question_role == "amount":
            match=re.fullmatch(r"\s*([$\u00a3\u20ac]?\s*"+numeric+r")\s*[.!]?\s*",text)
            if match: add("amount",match.start(1),match.end(1))
        # Numerically overlapping date/time/identifier hypotheses remain explicit.
        for candidate in candidates:
            competing=[other["kind"] for other in candidates+exclusions if other["kind"]!=candidate["kind"] and max(other["start"],candidate["start"])<min(other["end"],candidate["end"])]
            if competing:
                candidate["possible_kinds"]=sorted(set([candidate["kind"]]+competing))
                candidate["detector_status"]="conflicting_candidates"
        present={candidate["kind"] for candidate in candidates}
        status="overflow" if len(candidates)>16 or len(clauses)>12 else "conflicting_candidates" if any(c["detector_status"]=="conflicting_candidates" for c in candidates) else "candidate" if candidates else "no_candidate"
        return {"version":DETECTOR_VERSION,"status":status,"candidates":candidates,"candidate_count":len(candidates),"clauses":clauses,
                "competing_kind_spans":exclusions,"missing_kind_diagnostics":{kind:"detector_no_candidate" for kind in COMPONENT_NAMES if kind not in present},
                "absence_established":False,"surface_features_masked":False,"language_pattern_coverage_qualified":False}


    def align_candidates_v3(diagnostics,reviewed_components,whole_turn_absence=None):
        """Exact kind/Unicode spans ONLY. Never use nearest span as a training target.

        Candidate validity negatives require explicit reviewed absence for that kind.
        Completion/polarity labels attach only to exact matched reviewed masks.
        """
        rows=[]; matched=set()
        for candidate in diagnostics["candidates"]:
            hits=[(i,gold) for i,gold in enumerate(reviewed_components) if gold["kind"]==candidate["kind"] and gold["start"]==candidate["start"] and gold["end"]==candidate["end"]]
            row={"candidate":candidate,"validity_label":None,"validity_mask":False,"completion_label":None,"completion_mask":False,"polarity_label":None,"polarity_mask":False}
            if len(hits)==1:
                index,gold=hits[0]; matched.add(index)
                row.update(validity_label=True,validity_mask=gold.get("presence_mask") is True,
                           completion_label=gold.get("completion"),completion_mask=gold.get("completion_mask") is True,
                           polarity_label=gold.get("polarity"),polarity_mask=gold.get("polarity_mask") is True)
            elif (whole_turn_absence or {}).get(candidate["kind"]) is True:
                row.update(validity_label=False,validity_mask=True)
            rows.append(row)
        return {"rows":rows,"missed_reviewed_component_indices":[i for i in range(len(reviewed_components)) if i not in matched],
                "unreviewed_candidates":sum(not r["validity_mask"] for r in rows),"oracle_span_metric":False}
    """Pure structural output guard; supported json/re/builtins only."""


    def schema_errors_v3(value,schema,root=None,path="$"):
        root=root or schema
        if "$ref" in schema:
            node=root
            for name in schema["$ref"].split("/")[1:]: node=node[name]
            return schema_errors_v3(value,node,root,path)
        if "anyOf" in schema:
            return [] if any(not schema_errors_v3(value,choice,root,path) for choice in schema["anyOf"]) else [path+":anyOf"]
        if "enum" in schema and not any(type(value) is type(item) and value==item for item in schema["enum"]): return [path+":enum"]
        kind=schema.get("type")
        valid={"object":type(value) is dict,"array":type(value) is list,"string":type(value) is str,
               "integer":type(value) is int,"number":type(value) in (int,float) and -float("inf")<value<float("inf"),
               "null":value is None,"boolean":type(value) is bool}.get(kind,True)
        if not valid: return [path+":type_or_nonfinite"]
        errors=[]
        if kind=="object":
            properties=schema.get("properties",{})
            errors += [path+":missing:"+key for key in schema.get("required",[]) if key not in value]
            if schema.get("additionalProperties") is False: errors += [path+":extra:"+key for key in value if key not in properties]
            for key,item in value.items():
                if key in properties: errors += schema_errors_v3(item,properties[key],root,path+"."+key)
        if kind=="array":
            if not schema.get("minItems",0)<=len(value)<=schema.get("maxItems",len(value)): errors.append(path+":size")
            if schema.get("uniqueItems") and any(item in value[:i] for i,item in enumerate(value)): errors.append(path+":duplicate")
            for i,item in enumerate(value): errors += schema_errors_v3(item,schema.get("items",{}),root,path+"["+str(i)+"]")
        if kind=="string":
            if not schema.get("minLength",0)<=len(value)<=schema.get("maxLength",len(value)): errors.append(path+":length")
            if schema.get("pattern") and re.search(schema["pattern"],value) is None: errors.append(path+":pattern")
        if kind in ("number","integer"):
            if value<schema.get("minimum",value) or value>schema.get("maximum",value): errors.append(path+":range")
        return errors


    def wire_errors_v3(proposal,snapshot,schema):
        errors=schema_errors_v3(proposal,schema)
        text=snapshot.get("utterance",{}).get("text","")
        indices={target["index"] for target in snapshot.get("targets",[]) if type(target) is dict and type(target.get("index")) is int}
        def walk(value):
            if type(value) is dict:
                if set(value)=={"turn_id","start","end","role"}:
                    if value["turn_id"]!=snapshot.get("turn_id") or type(value["start"]) is not int or type(value["end"]) is not int or not 0<=value["start"]<value["end"]<=len(text): errors.append("invalid_source_span")
                for item in value.values(): walk(item)
            elif type(value) is list:
                for item in value: walk(item)
        walk(proposal)
        clauses=proposal.get("clauses",[])
        ids=[clause.get("clause_id") for clause in clauses]
        if len(ids)!=len(set(ids)): errors.append("duplicate_clause")
        for clause in clauses:
            names=[component.get("name") for component in clause.get("components",[])]
            if len(names)!=len(set(names)): errors.append("duplicate_component")
            if any(ref.get("index") not in indices for ref in clause.get("target_refs",[])): errors.append("unknown_target")
        return errors
    """New shadow wrapper: pure proposal wire plus separate source/candidate diagnostics.

    Frozen v2 learned weights reused as exposed diagnostics; no fit/qualification.
    Candidate-validity, clause identity, target, correction and consent remain masks.
    """


    def _decision_v3(score,reason="untrained_head"):
        return {"score":score,"calibrated_probability":None,"calibration_id":None,"decision":"abstain","abstain_reason":reason}


    def _span_v3(snapshot,start,end,role):
        return {"turn_id":snapshot["turn_id"],"start":start,"end":end,"role":role}


    def predict_v3(snapshot,bundle,trusted,registry,state,schema,include_context=True,security_fields=None):
        if not isinstance(trusted,TrustedCallV3): raise InputRejected("Independent source wrapper required")
        try:
            reason=validate_ingress_v3(snapshot,trusted)
            if reason: return neutral_v2(trusted.binding_context,reason),{"ingress_reason":reason,"qualified":False}
            if bundle.get("model_id")!=trusted.binding_context.model_id:
                return neutral_v2(trusted.binding_context,"stale_binding"),{"ingress_reason":"stale_binding","qualified":False}
            model=bundle["model"]
            if model.get("format") != "context-sparse-diagnostic-v2":
                return neutral_v2(trusted.binding_context,"unknown_schema"),{"qualified":False}
            text=snapshot["utterance"]["text"]
            detector=detect_candidates_v3(text,snapshot["question"]["role"] if include_context else "none",snapshot["targets"],security_fields)
            if snapshot["question"]["role"]=="security":
                detector=detect_candidates_v3(text,"security",snapshot["targets"],security_fields)
                return neutral_v2(trusted.binding_context,"untrained_head"),{"detector":detector,"surface_features_masked":True,"qualified":False}
            if detector["status"]=="overflow":
                return neutral_v2(trusted.binding_context,"size_limit"),{"detector":detector,"qualified":False}
            vector=feature_v2(snapshot,include_context=include_context)
            scores=distribution_v2(model["heads"]["primary"],vector)
            label=max(scores,key=lambda key:(scores[key],key))
            primary=dict(_decision_v3(scores[label],"uncalibrated"),label=label,evidence=[_span_v3(snapshot,0,len(text),"intent")])
            secondary=[]
            for name,head in sorted(model["secondary"].items()):
                score=binary_score_v2(head,vector)
                if score>=.5 and name not in {label,"unknown"}: secondary.append(dict(_decision_v3(score,"uncalibrated"),label=name,evidence=primary["evidence"]))
            qualifiers=qualifiers_v2(snapshot)
            raw_components=[]
            for candidate in detector["candidates"]:
                # Actual detector span supplies these features. Local right-context
                # is reported but frozen v2 has no trained right-context features.
                features=feature_v2(snapshot,candidate,include_context)
                completion=distribution_v2(model["heads"]["component_completion"],features)
                polarity=distribution_v2(model["heads"]["component_polarity"],features)
                raw_components.append({"candidate":candidate,"completion_scores":completion,"polarity_scores":polarity,
                                       "local_right_context_supported_by_head":False,"candidate_validity_head_trained":False})
            clauses=[]
            for local in detector["clauses"]:
                components=[]
                for name in ("amount","date","time","security_answer","recipient","allocation"):
                    rows=[c for c in detector["candidates"] if c["kind"]==name and c["clause_id_or_unknown"]==local["clause_id"]]
                    if not rows: continue
                    # Missing hypotheses omitted. Competing hypotheses keep all
                    # original spans; validity/scope heads unavailable => uncertainty.
                    components.append({"name":name,"completion":"ambiguous","polarity":"unknown",
                                       "evidence":[_span_v3(snapshot,r["start"],r["end"],"value") for r in rows],
                                       "reference":None,"confidence":_decision_v3(0.)})
                unknown=dict(_decision_v3(0.),label="unknown",evidence=[_span_v3(snapshot,local["start"],local["end"],"intent")])
                clauses.append({"clause_id":local["clause_id"],"intent":unknown,"scope":"unresolved","target_refs":[],
                                "collective_id":None,"amount_scope":"unresolved","components":components,
                                "qualifiers":[q for q in qualifiers if local["start"]<=q["start"] and q["end"]<=local["end"]],"offer_reference":None})
            new_terms=bool(detector["candidates"] or any(q["role"]=="correction" for q in qualifiers))
            reference=resolve_reference_v3(snapshot,label,trusted,registry,state,new_terms) if include_context else {"candidate_id_or_null":None,"reason":"unresolved_reference","reference_kind":None,"context_disabled":True}
            proposal=neutral_v2(trusted.binding_context,"uncalibrated")
            proposal.update(primary=primary,secondary=secondary,clauses=clauses)
            if reference["reference_kind"]=="readback": proposal["consent_signal"]["candidate_readback_id"]=reference["candidate_id_or_null"]
            proposal["consent_signal"]["has_new_terms"]=True if new_terms else "unknown"
            errors=wire_errors_v3(proposal,snapshot,schema)
            if errors: proposal=neutral_v2(trusted.binding_context,"runtime_failure")
            return proposal,{"detector":detector,"component_scores_on_actual_candidates":raw_components,"reference":reference,"wire_errors":errors,
                             "trained_weights":"frozen exposed v2; no refit","all_candidate_validity_and_scope_masks_unqualified":True,"qualified":False}
        except (KeyError,TypeError,ValueError,IndexError,AttributeError,OverflowError,ProposalOverflow):
            return neutral_v2(trusted.binding_context,"runtime_failure"),{"runtime_failure":True,"qualified":False}
